//! RPG Maker MV/MZ `js/plugins.js` reader/editor.
//!
//! The editor writes:
//!
//! ```text
//! // Generated by RPG Maker.
//! // Do not edit this file directly.
//! var $plugins =
//! [
//! {"name":"A","status":true,"description":"…","parameters":{"k":"v"}},
//! …
//! ];
//! ```
//!
//! Parameter values are strings; struct/array parameters hold JSON text nested
//! inside those strings, recursively. Everything is addressed through
//! [`json_span`], so edits rewrite only the targeted string literals and every
//! other byte — comments, line endings, a BOM, untouched plugins — is kept.

use std::ops::Range;
use std::sync::LazyLock;

use regex::Regex;

use super::json_span::{self, JsonSpanError, SpanNode};

#[derive(Debug, thiserror::Error, PartialEq, Eq)]
pub enum PluginsJsError {
    #[error("plugins.js has no `var $plugins =` assignment")]
    NoAssignment,
    #[error("plugins.js array is not valid JSON: {0}")]
    Json(#[from] JsonSpanError),
    #[error("`$plugins` is not an array")]
    NotAnArray,
    #[error("plugin entry #{0} is malformed: {1}")]
    BadEntry(usize, &'static str),
    #[error("no plugin named {name} (occurrence {occurrence})")]
    UnknownPlugin { name: String, occurrence: u32 },
}

static RE_ASSIGNMENT: LazyLock<Regex> =
    LazyLock::new(|| Regex::new(r"var\s+\$plugins\s*=").expect("RE_ASSIGNMENT must compile"));

/// One `$plugins` entry.
#[derive(Debug, Clone, PartialEq)]
pub struct PluginEntry {
    /// Position in the `$plugins` array (load order).
    pub index: usize,
    pub name: String,
    /// 1-based rank among entries sharing `name` (normally 1).
    pub occurrence: u32,
    pub status: bool,
    /// The parsed `parameters` object.
    parameters: SpanNode,
    /// Byte span of the whole entry object in the file text.
    span: Range<usize>,
}

impl PluginEntry {
    /// Every string leaf of the parameters, descending into JSON-in-string;
    /// paths start with the parameter name.
    pub fn parameter_leaves(&self) -> Vec<(Vec<String>, String)> {
        let mut leaves = Vec::new();
        json_span::visit_string_leaves(&self.parameters, &mut |path, value| {
            leaves.push((path.to_vec(), value.to_string()));
        });
        leaves
    }
}

/// Parsed `plugins.js`.
#[derive(Debug, Clone)]
pub struct PluginsJs {
    text: String,
    array_span: Range<usize>,
    entries: Vec<PluginEntry>,
}

impl PluginsJs {
    pub fn parse(text: &str) -> Result<Self, PluginsJsError> {
        let assignment = RE_ASSIGNMENT
            .find(text)
            .ok_or(PluginsJsError::NoAssignment)?;
        let (root, _) = json_span::parse_at(text, assignment.end())?;
        let SpanNode::Array { items, span } = &root else {
            return Err(PluginsJsError::NotAnArray);
        };
        let mut entries = Vec::with_capacity(items.len());
        for (index, item) in items.iter().enumerate() {
            let name = item
                .member("name")
                .and_then(SpanNode::as_str)
                .ok_or(PluginsJsError::BadEntry(index, "missing name"))?
                .to_string();
            let status = match item.member("status") {
                Some(SpanNode::Scalar { span }) => &text[span.clone()] == "true",
                _ => return Err(PluginsJsError::BadEntry(index, "missing status")),
            };
            let parameters = match item.member("parameters") {
                Some(node @ SpanNode::Object { .. }) => node.clone(),
                _ => return Err(PluginsJsError::BadEntry(index, "missing parameters")),
            };
            let occurrence = entries
                .iter()
                .filter(|entry: &&PluginEntry| entry.name == name)
                .count() as u32
                + 1;
            entries.push(PluginEntry {
                index,
                name,
                occurrence,
                status,
                parameters,
                span: item.span(),
            });
        }
        Ok(Self {
            text: text.to_string(),
            array_span: span.clone(),
            entries,
        })
    }

    pub fn entries(&self) -> &[PluginEntry] {
        &self.entries
    }

    /// Raw source text of one entry object.
    pub fn entry_text(&self, entry: &PluginEntry) -> &str {
        &self.text[entry.span.clone()]
    }

    /// Text before the `$plugins` array (header comments, assignment).
    pub fn prefix(&self) -> &str {
        &self.text[..self.array_span.start]
    }

    /// Text after the `$plugins` array (`;`, trailing newline).
    pub fn suffix(&self) -> &str {
        &self.text[self.array_span.end..]
    }

    pub fn entry(&self, name: &str, occurrence: u32) -> Option<&PluginEntry> {
        self.entries
            .iter()
            .find(|entry| entry.name == name && entry.occurrence == occurrence)
    }

    /// Resolve a parameter path (parameter name first) to its string value.
    pub fn get(
        &self,
        name: &str,
        occurrence: u32,
        path: &[String],
    ) -> Result<String, PluginsJsError> {
        let entry = self
            .entry(name, occurrence)
            .ok_or_else(|| PluginsJsError::UnknownPlugin {
                name: name.to_string(),
                occurrence,
            })?;
        let mut full = vec![entry.index.to_string(), "parameters".to_string()];
        full.extend_from_slice(path);
        Ok(json_span::get_string(
            &self.text[self.array_span.clone()],
            &full,
        )?)
    }

    /// Return the file text with `edits` applied — `(plugin name, occurrence,
    /// parameter path, new value)` — leaving every other byte untouched.
    pub fn apply_edits(
        &self,
        edits: &[(String, u32, Vec<String>, String)],
    ) -> Result<String, PluginsJsError> {
        let mut paths = Vec::with_capacity(edits.len());
        for (name, occurrence, path, value) in edits {
            let entry =
                self.entry(name, *occurrence)
                    .ok_or_else(|| PluginsJsError::UnknownPlugin {
                        name: name.clone(),
                        occurrence: *occurrence,
                    })?;
            let mut full = vec![entry.index.to_string(), "parameters".to_string()];
            full.extend_from_slice(path);
            paths.push((full, value.clone()));
        }
        let array = &self.text[self.array_span.clone()];
        let edited = json_span::apply_edits(array, &paths)?;
        let mut out = String::with_capacity(self.text.len() + edited.len() - array.len());
        out.push_str(&self.text[..self.array_span.start]);
        out.push_str(&edited);
        out.push_str(&self.text[self.array_span.end..]);
        Ok(out)
    }
}

/// Segment key for a plugin parameter leaf:
/// `plugin:v1:` + RFC 6901 pointer `/<plugin name>/<occurrence>/<param>/<nested…>`.
pub const PLUGIN_KEY_PREFIX: &str = "plugin:v1:";

pub fn plugin_key(name: &str, occurrence: u32, path: &[String]) -> String {
    let mut key = String::from(PLUGIN_KEY_PREFIX);
    key.push('/');
    key.push_str(&json_span::escape_token(name));
    key.push('/');
    key.push_str(&occurrence.to_string());
    for token in path {
        key.push('/');
        key.push_str(&json_span::escape_token(token));
    }
    key
}

/// Inverse of [`plugin_key`]: `(name, occurrence, parameter path)`.
pub fn parse_plugin_key(key: &str) -> Option<(String, u32, Vec<String>)> {
    let pointer = key.strip_prefix(PLUGIN_KEY_PREFIX)?;
    let mut tokens = json_span::pointer_tokens(pointer).ok()?.into_iter();
    let name = tokens.next()?;
    let occurrence = tokens.next()?.parse().ok()?;
    let path: Vec<String> = tokens.collect();
    (!path.is_empty()).then_some((name, occurrence, path))
}

#[cfg(test)]
mod tests {
    use super::*;

    const SAMPLE: &str = "// Generated by RPG Maker.\r\n// Do not edit this file directly.\r\nvar $plugins =\r\n[\r\n{\"name\":\"nuun/NUUN_EnemyBook\",\"status\":true,\"description\":\"Enemy book\",\"parameters\":{\"CommandName\":\"エネミー図鑑\",\"PageSetting\":\"[\\\"{\\\\\\\"PageCategoryName\\\\\\\":\\\\\\\"基本情報\\\\\\\"}\\\"]\"}},\r\n{\"name\":\"Off\",\"status\":false,\"description\":\"\",\"parameters\":{\"x\":\"y\"}},\r\n{\"name\":\"Off\",\"status\":true,\"description\":\"\",\"parameters\":{}}\r\n];\r\n";

    #[test]
    fn parses_entries_status_and_duplicate_occurrences() {
        let plugins = PluginsJs::parse(SAMPLE).unwrap();
        let names: Vec<_> = plugins
            .entries()
            .iter()
            .map(|e| (e.name.as_str(), e.occurrence, e.status))
            .collect();
        assert_eq!(
            names,
            vec![
                ("nuun/NUUN_EnemyBook", 1, true),
                ("Off", 1, false),
                ("Off", 2, true)
            ]
        );
    }

    #[test]
    fn leaves_descend_into_nested_struct_arrays() {
        let plugins = PluginsJs::parse(SAMPLE).unwrap();
        let leaves = plugins.entries()[0].parameter_leaves();
        assert!(leaves.contains(&(vec!["CommandName".into()], "エネミー図鑑".into())));
        assert!(leaves.contains(&(
            vec!["PageSetting".into(), "0".into(), "PageCategoryName".into()],
            "基本情報".into()
        )));
    }

    #[test]
    fn unedited_file_round_trips_byte_for_byte() {
        let plugins = PluginsJs::parse(SAMPLE).unwrap();
        assert_eq!(plugins.apply_edits(&[]).unwrap(), SAMPLE);
        let with_bom = format!("\u{feff}{SAMPLE}");
        assert_eq!(
            PluginsJs::parse(&with_bom)
                .unwrap()
                .apply_edits(&[])
                .unwrap(),
            with_bom
        );
    }

    #[test]
    fn edits_touch_only_the_target_entry_line() {
        let plugins = PluginsJs::parse(SAMPLE).unwrap();
        let edited = plugins
            .apply_edits(&[(
                "nuun/NUUN_EnemyBook".into(),
                1,
                vec!["PageSetting".into(), "0".into(), "PageCategoryName".into()],
                "Basic info".into(),
            )])
            .unwrap();
        let reparsed = PluginsJs::parse(&edited).unwrap();
        assert_eq!(
            reparsed
                .get(
                    "nuun/NUUN_EnemyBook",
                    1,
                    &["PageSetting".into(), "0".into(), "PageCategoryName".into()]
                )
                .unwrap(),
            "Basic info"
        );
        let original_lines: Vec<_> = SAMPLE.split("\r\n").collect();
        let edited_lines: Vec<_> = edited.split("\r\n").collect();
        assert_eq!(original_lines.len(), edited_lines.len());
        for (index, (a, b)) in original_lines.iter().zip(&edited_lines).enumerate() {
            if index == 4 {
                assert_ne!(a, b);
            } else {
                assert_eq!(a, b, "line {index} must be untouched");
            }
        }
    }

    #[test]
    fn plugin_keys_round_trip_with_escaping() {
        let path = vec![
            "PageList1".to_string(),
            "11".to_string(),
            "param/Name".to_string(),
        ];
        let key = plugin_key("nuun/NUUN_EnemyBook", 1, &path);
        assert_eq!(
            key,
            "plugin:v1:/nuun~1NUUN_EnemyBook/1/PageList1/11/param~1Name"
        );
        assert_eq!(
            parse_plugin_key(&key),
            Some(("nuun/NUUN_EnemyBook".to_string(), 1, path))
        );
        assert_eq!(parse_plugin_key("/events/1"), None);
    }

    #[test]
    fn rejects_unreadable_files() {
        assert_eq!(
            PluginsJs::parse("var x = 1;").unwrap_err(),
            PluginsJsError::NoAssignment
        );
        assert!(matches!(
            PluginsJs::parse("var $plugins = {};"),
            Err(PluginsJsError::NotAnArray)
        ));
        assert!(PluginsJs::parse("var $plugins = [{\"name\":\"a\"}];").is_err());
        assert!(PluginsJs::parse(
            "var $plugins = [{\"name\":\"a\",\"status\":true,\"parameters\":{\"p\":\"\\ud800\"}}];"
        )
        .is_err());
    }
}
